def countRoutesWithDiagonals(grid):
    MOD = 10 ** 9 + 7
    n = len(grid[0])
    prev = [0] * n
    for r, row in enumerate(grid):
        cur = [0] * n
        for c in range(n):
            if row[c] == 1:
                continue
            if r == 0 and c == 0:
                cur[c] = 1
                continue
            s = prev[c]
            if c > 0:
                s += cur[c - 1] + prev[c - 1]
            cur[c] = s % MOD
        prev = cur
    return prev[-1]
